"""Generate long reasoning traces by continuing a short reasoning with Qwen3.

Modes:
  oo: continue the original (correct) short reasoning, `data["response"]`.
  xo: continue an incorrect short reasoning, read from
      `<wrong_cot>/{key}.json` (field "wrong_response").
"""

import argparse
import json
import os
import random
from queue import Queue
from threading import Lock, Thread
from typing import Tuple

from openai import OpenAI
from tqdm import tqdm

file_lock = Lock()

DESCRIPTION_NOTE = (
    "Note: The descriptions below are helpful hints, automatically generated by models, and may contain inaccuracies. "
    "Use the parts that seem relevant to the question and choices."
    "If information conflicts, prefer the evidence that is most directly supported by the question/choices and is most consistent with the overall context. "
)


def save_result(key: str, response: str, save_path: str):
    """Thread-safe result saving"""
    with file_lock:
        file_path = os.path.join(save_path, f"{key}.txt")
        os.makedirs(os.path.dirname(file_path), exist_ok=True)
        with open(file_path, "w") as f:
            f.write(response)


def build_user_prompt(
    data: dict, audio_description: str, short_reasoning: str, user_prompt_template: str
) -> Tuple[str, str]:

    audio_description = DESCRIPTION_NOTE + "\n\n" + audio_description

    prompt = user_prompt_template.replace("__QUESTION__", data["question"]).replace(
        "__AUDIO_DESCRIPTION__", audio_description
    )

    keyword = random.choice(
        [
            "Wait.",
            "Hmm.",
            "Alternatively,",
            "Let me check again.",
            "Let me listen again.",
            "Let me listen more carefully.",
        ]
    )
    prompt += f"<reasoning>\n{short_reasoning} {keyword}\n</reasoning>"

    return prompt, keyword


def worker_fn(
    task_queue: Queue,
    result_queue: Queue,
    progress_bar: tqdm,
    user_prompt_template: str,
    save_path: str,
    args,
):
    """Worker function for processing items"""
    client = OpenAI(
        base_url=args.vllm_base_url,
        api_key="EMPTY",
    )
    model = args.vllm_model

    while True:
        data = task_queue.get()
        if data is None:  # Termination signal
            task_queue.task_done()
            break

        try:
            key, entry, audio_description, short_reasoning = data
            (user_prompt, keyword) = build_user_prompt(
                entry, audio_description, short_reasoning, user_prompt_template
            )

            # API call
            completion = client.chat.completions.create(
                model=model,
                messages=[
                    {
                        "role": "user",
                        "content": [
                            {"type": "text", "text": user_prompt},
                        ],
                    },
                ],
                temperature=0.6,
                top_p=0.95,
                max_tokens=4096,
                extra_body={"top_k": 20, "min_p": 0},
                stream=False,
            )

            choice = completion.choices[0]
            finish_reason = getattr(choice, "finish_reason", None)

            if finish_reason == "length":
                raise ValueError("length exceeded")

            response = ""
            message = choice.message
            if hasattr(message, "content") and message.content:
                content = message.content.strip()

                # Avoid formatting error
                content = content.replace("<reasoning>", "").replace("</reasoning>", "")

                if content.startswith(keyword):
                    response = content
                elif keyword == "Alternatively,":
                    response = keyword + " " + content[0].lower() + content[1:]
                else:
                    response = keyword + " " + content
            if response == "":
                raise ValueError("Model response is empty")

            # Save result immediately
            save_result(key, response, save_path)
            result_queue.put((key, None))

        except Exception as e:
            result_queue.put((key, str(e)))
        finally:
            task_queue.task_done()
            progress_bar.update(1)


def parse_args():
    parser = argparse.ArgumentParser(
        description="Generating long CoT reasoning from Qwen3 by continuing a short reasoning"
    )
    parser.add_argument(
        "--mode",
        type=str,
        required=True,
        choices=["oo", "xo"],
        help="oo: continue the original correct reasoning; xo: continue an incorrect reasoning",
    )
    parser.add_argument(
        "--input",
        "-i",
        type=str,
        default="../examples/afthink_metadata_sample.json",
        help="Input JSON file containing metadata entries.",
    )
    parser.add_argument(
        "--user_prompt",
        "-up",
        type=str,
        default="long_reasoning_user_prompt.txt",
        help="File with user prompt",
    )
    parser.add_argument(
        "--save_path",
        "-s",
        type=str,
        default=None,
        help="Path to save long CoT files (default: ../../workdir/long_cot/{mode})",
    )
    parser.add_argument(
        "--description_path",
        "-d",
        type=str,
        default="../../workdir/descriptions",
        help="Path to audio descriptions",
    )
    parser.add_argument(
        "--wrong_cot",
        "-wc",
        type=str,
        default="../../workdir/wrong_cot",
        help="[xo] Path to wrong CoT files (JSON format with 'wrong_response' field)",
    )
    parser.add_argument(
        "--num_workers",
        "-w",
        type=int,
        default=256,
        help="Number of worker threads",
    )
    parser.add_argument(
        "--vllm_base_url",
        type=str,
        default="http://127.0.0.1:8004/v1",
        help="Base URL for vLLM server",
    )
    parser.add_argument(
        "--vllm_model",
        type=str,
        default="Qwen/Qwen3-Next-80B-A3B-Thinking-FP8",
        help="Model name for vLLM server",
    )
    args = parser.parse_args()
    if args.save_path is None:
        args.save_path = f"../../workdir/long_cot/{args.mode}"
    return args


def main():
    args = parse_args()

    # Load prompt and input data
    user_prompt_template = open(args.user_prompt, "r").read()
    input_data = json.load(open(args.input, "r"))
    os.makedirs(args.save_path, exist_ok=True)

    print(f"Mode: {args.mode}")
    print(f"Loaded {len(input_data)} entries from {args.input}")

    # Prepare tasks - skip already processed files
    tasks = []
    skipped = 0

    for key, data in tqdm(
        list(input_data.items()), dynamic_ncols=True, desc="Checking existing results"
    ):
        if "original_key" in data:
            description_key = data["original_key"]
        else:
            description_key = key

        description_file = os.path.join(args.description_path, f"{description_key}.txt")
        if not os.path.exists(description_file):
            print(f"Warning: Description file not found for {key}, skipping.")
            continue

        if args.mode == "xo":
            wrong_cot_file = os.path.join(args.wrong_cot, f"{key}.json")
            if not os.path.exists(wrong_cot_file):
                print(f"Warning: Wrong CoT file not found for {key}, skipping.")
                continue

        if "question" not in data or "response" not in data:
            print(f"Warning: No question or response found for {key}")
            continue

        # Check if result file already exists
        result_file = os.path.join(args.save_path, f"{key}.txt")
        if os.path.exists(result_file):
            skipped += 1
            continue

        audio_description = open(description_file, "r").read().strip()

        if args.mode == "oo":
            short_reasoning = data["response"]
        else:
            with open(wrong_cot_file, "r") as f:
                wrong_cot_data = json.load(f)
            if "wrong_response" not in wrong_cot_data:
                print(f"Warning: 'wrong_response' not found in {wrong_cot_file}, skipping.")
                continue
            short_reasoning = wrong_cot_data["wrong_response"]

        tasks.append((key, data, audio_description, short_reasoning))

    print(f"Total files: {len(input_data)}")
    print(f"Already processed: {skipped}")
    print(f"To process: {len(tasks)}")

    if len(tasks) == 0:
        print("All files already processed!")
        return

    print(f"Model: {args.vllm_model}")

    # Setup queues and progress bar
    task_queue = Queue(maxsize=args.num_workers * 2)
    result_queue = Queue()
    progress_bar = tqdm(
        total=len(tasks),
        desc=f"Generating Long Reasoning Trace ({args.mode})",
        dynamic_ncols=True,
    )

    # Start worker threads
    threads = []
    for _ in range(args.num_workers):
        thread = Thread(
            target=worker_fn,
            args=(
                task_queue,
                result_queue,
                progress_bar,
                user_prompt_template,
                args.save_path,
                args,
            ),
        )
        thread.start()
        threads.append(thread)

    # Add tasks to queue
    for task in tasks:
        task_queue.put(task)

    # Send termination signals
    for _ in range(args.num_workers):
        task_queue.put(None)

    # Wait for completion
    task_queue.join()
    for thread in threads:
        thread.join()

    progress_bar.close()

    # Collect results
    result_cnt = 0
    errors = []

    while not result_queue.empty():
        key, error = result_queue.get()
        if error:
            errors.append(f"{key}: {error}")
        else:
            result_cnt += 1

    # Print summary
    print(f"\nProcessed: {len(tasks)}")
    print(f"Successful: {result_cnt}")
    print(f"Errors: {len(errors)}")
    print(f"Skipped (already done): {skipped}")
    print(f"Individual files saved to: {args.save_path}")

    if errors:
        error_file = f"long_cot_{args.mode}_errors.txt"
        with open(error_file, "w") as f:
            f.write("\n".join(errors))
        print(f"Errors saved to {error_file}")


if __name__ == "__main__":
    main()
